from dataclasses import dataclass

@dataclass
class Student:
    name: str
    age: int
    score: int

class StudentRoster:
    def __init__(self):
        self.students = []

    def add_student(self, name, age, score):
        self.students.append(Student(name, age, score))

    def average_score(self):
        scores = [student.score for student in self.students]
        return sum(scores) / len(scores) if scores else 0.0

    def top_students(self, n):
        sorted_students = sorted(self.students, key=lambda student: student.score, reverse=True)
        return [(student.name, student.age, student.score) for student in sorted_students[:n]]
